INSERT INTO factory_current_product_master AS s (id, data, action_type, registered_by, registered_at, _k_product_code)
SELECT * FROM (
    SELECT t3._r_id AS id, t3._r_data AS data, t3._r_action_type AS action_type, t3._r_registered_by AS registered_by, t3._r_registered_at AS registered_at, t3.product_code AS _k_product_code
    FROM (
        SELECT DISTINCT ON (t2.product_code COLLATE "C") t2.product_code, t2._o_registered_at, t2._o_id, t2._r_id, t2._r_data, t2._r_action_type, t2._r_registered_by, t2._r_registered_at
        FROM (
            SELECT ((t1.data ->> 'product_code')::text) AS product_code, t1.registered_at AS _o_registered_at, t1.id AS _o_id, t1.id AS _r_id, t1.data AS _r_data, t1.action_type AS _r_action_type, t1.registered_by AS _r_registered_by, t1.registered_at AS _r_registered_at
            FROM product_events AS t1
        ) AS t2
        WHERE (NOT (t2.product_code IS NULL))
        ORDER BY t2.product_code COLLATE "C", t2._o_registered_at DESC, t2._o_id DESC
    ) AS t3
) AS v
ON CONFLICT (_k_product_code) DO UPDATE SET id = EXCLUDED.id, data = EXCLUDED.data, action_type = EXCLUDED.action_type, registered_by = EXCLUDED.registered_by, registered_at = EXCLUDED.registered_at
WHERE (((EXCLUDED.registered_at IS NULL AND s.registered_at IS NOT NULL) OR EXCLUDED.registered_at > s.registered_at) OR (EXCLUDED.registered_at IS NOT DISTINCT FROM s.registered_at AND ((EXCLUDED.id IS NULL AND s.id IS NOT NULL) OR EXCLUDED.id > s.id)));

-- 当前状态表: factory_current_store_notices(逻辑表的每个键一行 = 原始表 store_notice_events 里登记顺序最新的一行,含删除的墓碑)。
-- 由工厂生成(docs/design/current-state.md),不要手改;触发器在写原始表的同一个事务里维护它。
CREATE TABLE IF NOT EXISTS factory_current_store_notices (
    id int8,
    data jsonb,
    action_type int4,
    registered_by text,
    registered_at timestamptz,
    _k_store_code int4,
    _k_notice_no int4,
    CONSTRAINT factory_current_store_notices_key UNIQUE NULLS NOT DISTINCT (_k_store_code, _k_notice_no)
);
CREATE INDEX IF NOT EXISTS factory_current_store_notices_key_idx ON factory_current_store_notices ((CASE WHEN (data ->> 'store_code') ~ '^[ \t\n\r\f\v]*[+-]?[0-9]+[ \t\n\r\f\v]*$' THEN (CASE WHEN ((data ->> 'store_code')::numeric BETWEEN -2147483648 AND 2147483647) THEN ((data ->> 'store_code')::int4) END) END), (CASE WHEN (data ->> 'notice_no') ~ '^[ \t\n\r\f\v]*[+-]?[0-9]+[ \t\n\r\f\v]*$' THEN (CASE WHEN ((data ->> 'notice_no')::numeric BETWEEN -2147483648 AND 2147483647) THEN ((data ->> 'notice_no')::int4) END) END));
CREATE INDEX IF NOT EXISTS factory_current_store_notices_store_code_idx ON factory_current_store_notices ((CASE WHEN (data ->> 'store_code') ~ '^[ \t\n\r\f\v]*[+-]?[0-9]+[ \t\n\r\f\v]*$' THEN (CASE WHEN ((data ->> 'store_code')::numeric BETWEEN -2147483648 AND 2147483647) THEN ((data ->> 'store_code')::int4) END) END));
CREATE OR REPLACE FUNCTION factory_current_store_notices_ins() RETURNS trigger LANGUAGE plpgsql AS $factory$
BEGIN
    INSERT INTO factory_current_store_notices AS s (id, data, action_type, registered_by, registered_at, _k_store_code, _k_notice_no)
    SELECT * FROM (
        SELECT t3._r_id AS id, t3._r_data AS data, t3._r_action_type AS action_type, t3._r_registered_by AS registered_by, t3._r_registered_at AS registered_at, t3.store_code AS _k_store_code, t3.notice_no AS _k_notice_no
        FROM (
            SELECT DISTINCT ON (t2.store_code, t2.notice_no) t2.store_code, t2.notice_no, t2._o_registered_at, t2._o_id, t2._r_id, t2._r_data, t2._r_action_type, t2._r_registered_by, t2._r_registered_at
            FROM (
                SELECT ((CASE WHEN (t1.data ->> 'store_code') ~ '^[ \t\n\r\f\v]*[+-]?[0-9]+[ \t\n\r\f\v]*$' THEN (t1.data ->> 'store_code') ELSE '✗' || (t1.data ->> 'store_code') END)::int4) AS store_code, ((CASE WHEN (t1.data ->> 'notice_no') ~ '^[ \t\n\r\f\v]*[+-]?[0-9]+[ \t\n\r\f\v]*$' THEN (t1.data ->> 'notice_no') ELSE '✗' || (t1.data ->> 'notice_no') END)::int4) AS notice_no, t1.registered_at AS _o_registered_at, t1.id AS _o_id, t1.id AS _r_id, t1.data AS _r_data, t1.action_type AS _r_action_type, t1.registered_by AS _r_registered_by, t1.registered_at AS _r_registered_at
                FROM factory_new AS t1
            ) AS t2
            WHERE ((NOT (t2.store_code IS NULL)) AND (NOT (t2.notice_no IS NULL)))
            ORDER BY t2.store_code, t2.notice_no, t2._o_registered_at DESC, t2._o_id DESC
        ) AS t3
    ) AS v
    ON CONFLICT (_k_store_code, _k_notice_no) DO UPDATE SET id = EXCLUDED.id, data = EXCLUDED.data, action_type = EXCLUDED.action_type, registered_by = EXCLUDED.registered_by, registered_at = EXCLUDED.registered_at
    WHERE (((EXCLUDED.registered_at IS NULL AND s.registered_at IS NOT NULL) OR EXCLUDED.registered_at > s.registered_at) OR (EXCLUDED.registered_at IS NOT DISTINCT FROM s.registered_at AND ((EXCLUDED.id IS NULL AND s.id IS NOT NULL) OR EXCLUDED.id > s.id)));
RETURN NULL;
END
